package thaumichorizons;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.node.*;
import thaumcraft.wand.*;
@GameTestHolder(ThaumicHorizons.ID)
@PrefixGameTestTemplate(false)
public final class RiftGameTests {
    @GameTest(template="test/platform") public static void nodeCheatPreservesBaseAspectsWithoutConsumption(GameTestHelper h){var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos,thaumcraft.registry.ModBlocks.AURA_NODE.get().defaultBlockState());var node=(NodeBlockEntity)h.getLevel().getBlockEntity(pos);node.setAspects(new AspectList().add(Aspect.AIR,30).add(Aspect.MAGIC,12));var player=h.makeMockPlayer(GameType.CREATIVE);var stack=new ItemStack(Content.item("node_cheat"));player.setItemInHand(InteractionHand.MAIN_HAND,stack);stack.useOn(new net.minecraft.world.item.context.UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(pos.getCenter(),Direction.UP,pos,false)));h.assertTrue(h.getLevel().getBlockEntity(pos) instanceof Vortex,"node cheat did not convert node");var vortex=(Vortex)h.getLevel().getBlockEntity(pos);h.assertTrue(vortex.cheat&&vortex.aspects.getAmount(Aspect.AIR)==30&&vortex.aspects.getAmount(Aspect.MAGIC)==12&&stack.getCount()==1,"node cheat lost original aura or consumed creative tool");h.succeed();}
    private static EnergizedNodeBlockEntity energized(GameTestHelper h,BlockPos pos){var level=h.getLevel();level.setBlockAndUpdate(pos.below(),thaumcraft.registry.ModBlocks.NODE_STABILIZER.get().defaultBlockState());level.setBlockAndUpdate(pos.above(),thaumcraft.registry.ModBlocks.NODE_TRANSDUCER.get().defaultBlockState());level.setBlockAndUpdate(pos,thaumcraft.registry.ModBlocks.ENERGIZED_AURA_NODE.get().defaultBlockState());var node=(EnergizedNodeBlockEntity)level.getBlockEntity(pos);node.setAspects(new AspectList().add(Aspect.AIR,20).add(Aspect.FIRE,10));node.setupNode();return node;}
    private static RiftDevices.Amplifier amplifier(GameTestHelper h,BlockPos node,Direction facing){var pos=node.relative(facing);h.getLevel().setBlockAndUpdate(pos,RiftDevices.AMPLIFIER.get().defaultBlockState().setValue(RiftDevices.FACING,facing));h.getLevel().setBlockAndUpdate(pos.above(),Blocks.REDSTONE_BLOCK.defaultBlockState());var amplifier=(RiftDevices.Amplifier)h.getLevel().getBlockEntity(pos);RiftDevices.Amplifier.tick(h.getLevel(),pos,amplifier.getBlockState(),amplifier);return amplifier;}
    @GameTest(template="test/platform") public static void amplifierAddsTenAuraAndRemovesExactlyThatBoost(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,4,3));var node=energized(h,pos);var amplifier=amplifier(h,pos,Direction.EAST);h.assertTrue(amplifier.active&&node.getAuraBase().getAmount(Aspect.AIR)==30&&node.getAuraBase().getAmount(Aspect.FIRE)==20,"amplifier did not add ten aura");h.getLevel().removeBlock(amplifier.getBlockPos().above(),false);RiftDevices.Amplifier.tick(h.getLevel(),amplifier.getBlockPos(),amplifier.getBlockState(),amplifier);h.assertTrue(!amplifier.active&&node.getAuraBase().getAmount(Aspect.AIR)==20&&node.getAuraBase().getAmount(Aspect.FIRE)==10,"turning amplifier off did not undo boost");h.succeed();
    }
    @GameTest(template="test/platform") public static void fourthAmplifierCreatesOriginalOverloadRift(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,4,3));energized(h,pos);var amps=new ArrayList<RiftDevices.Amplifier>();for(var face:Direction.Plane.HORIZONTAL)amps.add(amplifier(h,pos,face));var first=amps.getFirst();first.count=49;RiftDevices.Amplifier.tick(h.getLevel(),first.getBlockPos(),first.getBlockState(),first);h.assertTrue(h.getLevel().getBlockEntity(pos) instanceof Vortex,"four active amplifiers did not open rift");var vortex=(Vortex)h.getLevel().getBlockEntity(pos);h.assertTrue(vortex.aspects.getAmount(Aspect.AIR)==50&&vortex.aspects.getAmount(Aspect.FIRE)==40&&!vortex.cheat,"overload transferred wrong original aura");vortex.cheat=true;vortex.ateDevices=true;h.succeed();
    }
    @GameTest(template="test/platform") public static void stabilizationRemembersHungryTypeUntilLastBeamIsGone(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,4,3));h.getLevel().setBlockAndUpdate(pos,thaumcraft.registry.ModBlocks.AURA_NODE.get().defaultBlockState());var node=(NodeBlockEntity)h.getLevel().getBlockEntity(pos);node.setNodeType(NodeType.HUNGRY);var devices=new ArrayList<RiftDevices.Stabilizer>();for(var direction:new Direction[]{Direction.EAST,Direction.WEST}){var source=pos.relative(direction,2);h.getLevel().setBlockAndUpdate(source,RiftDevices.STABILIZER.get().defaultBlockState().setValue(RiftDevices.FACING,direction.getOpposite()));h.getLevel().setBlockAndUpdate(source.above(),Blocks.REDSTONE_BLOCK.defaultBlockState());var device=(RiftDevices.Stabilizer)h.getLevel().getBlockEntity(source);device.refresh();devices.add(device);}h.assertTrue(node.getNodeType()==NodeType.NORMAL,"hungry node not stabilized");h.getLevel().removeBlock(devices.getFirst().getBlockPos(),false);h.assertTrue(node.getNodeType()==NodeType.NORMAL,"removing one of two beams restored hunger");h.getLevel().removeBlock(devices.getLast().getBlockPos(),false);h.assertTrue(node.getNodeType()==NodeType.HUNGRY,"last beam did not restore original node type");node.setNodeType(NodeType.NORMAL);h.succeed();
    }
    @GameTest(template="test/platform") public static void sixStabilizersStopRiftAgingAndKeepCountAfterReload(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,4,3));h.getLevel().setBlockAndUpdate(pos,Vortex.BLOCK.get().defaultBlockState());var node=(Vortex)h.getLevel().getBlockEntity(pos);node.aspects.add(Aspect.AIR,20);node.count=100;node.ateDevices=true;
        for(var face:Direction.values()){var source=pos.relative(face,2);h.getLevel().setBlockAndUpdate(source,RiftDevices.STABILIZER.get().defaultBlockState().setValue(RiftDevices.FACING,face.getOpposite()));var power=source.relative(face.getAxis()==Direction.Axis.Y?Direction.EAST:Direction.UP);h.getLevel().setBlockAndUpdate(power,Blocks.REDSTONE_BLOCK.defaultBlockState());}
        h.assertValueEqual(RiftDevices.countBeams(h.getLevel(),pos),6,"six directional beams not found");Vortex.tick(h.getLevel(),pos,node.getBlockState(),node);h.assertValueEqual(node.count,100,"stable rift keeps aging");var saved=node.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new Vortex(pos,node.getBlockState());restored.loadWithComponents(saved,h.getLevel().registryAccess());h.assertTrue(restored.count==100&&restored.aspects.getAmount(Aspect.AIR)==20,"rift reload lost age or aura");node.cheat=true;h.succeed();
    }
    @GameTest(template="test/platform") public static void riftCraftsPuttyAndChargedWandWithoutOverstackingOrRefilling(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos,Vortex.BLOCK.get().defaultBlockState());var node=(Vortex)h.getLevel().getBlockEntity(pos);node.cheat=true;node.aspects.add(Aspect.AIR,20);var putty=new ItemEntity(h.getLevel(),pos.getX(),pos.getY(),pos.getZ(),new ItemStack(thaumcraft.registry.ModItems.VOID_METAL_INGOT.get(),64));h.assertTrue(node.voidCraft(putty)&&putty.isRemoved()&&node.outputs.size()==4&&node.outputs.stream().mapToInt(ItemStack::getCount).sum()==64&&node.outputs.stream().allMatch(stack->stack.getCount()<=stack.getMaxStackSize()),"void putty conversion lost or overstacks output");var raw=new ItemEntity(h.getLevel(),pos.getX(),pos.getY(),pos.getZ(),new ItemStack(Content.item("crystal_wand")));node.voidCraft(raw);var wand=node.outputs.getLast();h.assertTrue(wand.is(Content.item("disposable_wand"))&&Wands.getVis(wand,Aspect.AIR)==25000&&Wands.getAspectsWithRoom(wand).isEmpty(),"vortex did not charge disposable wand correctly");var saved=node.saveWithFullMetadata(h.getLevel().registryAccess());var loaded=new Vortex(pos,node.getBlockState());loaded.loadWithComponents(saved,h.getLevel().registryAccess());h.assertTrue(loaded.outputs.size()==5&&Wands.getVis(loaded.outputs.getLast(),Aspect.FIRE)==25000,"stored outputs lost on reload");h.succeed();
    }
    @GameTest(template="test/platform") public static void stableCreativeVortexPickKeepsItsSafeVariant(GameTestHelper h){var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos,Vortex.BLOCK.get().defaultBlockState());var node=(Vortex)h.getLevel().getBlockEntity(pos);node.cheat=true;var player=h.makeMockPlayer(GameType.CREATIVE);var picked=Vortex.BLOCK.get().getCloneItemStack(node.getBlockState(),new BlockHitResult(pos.getCenter(),Direction.UP,pos,false),h.getLevel(),pos,player);h.assertTrue(picked.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getBoolean("thStableVortex"),"middle click turned stable creative rift into destructive rift");h.succeed();}
}
